def can_win_game(S):
    n = len(S)
    flips = [0] * (n + 1)

    for i in range(n):
        if S[i] == '1':
            flips[i] += 1
            flips[i + 1] -= 1

    current_flips = 0
    for flip in flips:
        current_flips += flip
        if current_flips % 2 == 0:
            return "LOSE"

    return "WIN"

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    T = int(data[0])
    index = 1
    results = []

    for _ in range(T):
        S = data[index]
        index += 1
        result = can_win_game(S)
        results.append(result)

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
